        try:
            text = _render_dashboard_history(args.history)
        except Exception as exc:
            sys.stderr.write(f"ERROR {type(exc).__name__}: {exc}\n")
            return 1
        sys.stdout.write(text + "\n")
        return 0

    parser.print_help()
    return 0


if __name__ == "__main__":
